#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""PsychoPy presentation script generated by lexsync.

Design: es_ndensity    Language: spanish
Conditions file: es_ndensity_spanish_psychopy.csv

The onset trigger for each word is written to the parallel port on the exact
flip on which the word first appears, using ``win.callOnFlip``. This genuine
frame-locking is the timing improvement that motivates lexsync. A trailing
condition marker follows. When no parallel-port driver is present (a development
machine, macOS or continuous integration), a mock port prints the codes so the
script still runs end to end with no hardware.

Generated by lexsync; edit the design configuration rather than this file.
"""
import csv
import os

from psychopy import visual, core, event, parallel

HERE = os.path.dirname(os.path.abspath(__file__))
CONDITIONS_FILE = os.path.join(HERE, "es_ndensity_spanish_psychopy.csv")
TRIGGER_ADDRESS = 0x0378
RESET_AFTER_FRAMES = 2
WORD_DURATION_FRAMES = 30
FIXATION_FRAMES = 30
ISI_FRAMES = 15
INTER_TRIGGER_S = 0.01
FULLSCREEN = False
BLOCK_START_TRIGGER = 254
BLOCK_END_TRIGGER = 255


class MockPort:
    """Stand-in used when no parallel-port driver is available."""

    def setData(self, data):
        print("[lexsync mock trigger] %d" % int(data))


def open_port(address):
    """Return a real parallel port, or a MockPort when no driver/port exists."""
    try:
        port = parallel.ParallelPort(address=address)
        port.setData(0)  # the dummy backend raises NotImplementedError here
        return port
    except Exception:
        return MockPort()


def load_trials(path):
    with open(path, newline="", encoding="utf-8") as handle:
        return list(csv.DictReader(handle))


def present_trial(win, port, fixation, word_stim, trial):
    """Present one trial; the onset trigger is locked to the word's first flip."""
    target_trigger = int(trial["target_word_trigger"])
    condition_trigger = int(trial["condition_trigger"])

    for _ in range(FIXATION_FRAMES):
        fixation.draw()
        win.flip()

    word_stim.text = trial["word"]
    win.callOnFlip(port.setData, target_trigger)   # written on the onset flip
    for frame in range(WORD_DURATION_FRAMES):
        word_stim.draw()
        win.flip()
        if frame == RESET_AFTER_FRAMES:
            win.callOnFlip(port.setData, 0)

    # Trailing condition marker (sequence-ordered, after onset).
    core.wait(INTER_TRIGGER_S)
    port.setData(condition_trigger)
    core.wait(INTER_TRIGGER_S)
    port.setData(0)

    for _ in range(ISI_FRAMES):
        win.flip()

    keys = event.getKeys(keyList=["left", "right", "escape"])
    return keys[0] if keys else None


def main():
    trials = load_trials(CONDITIONS_FILE)
    win = visual.Window(size=(1280, 1024), color="black", units="pix", fullscr=FULLSCREEN)
    port = open_port(TRIGGER_ADDRESS)
    fixation = visual.TextStim(win, text="+", height=40, color="white")
    word_stim = visual.TextStim(win, text="", height=48, color="white", font="Courier New")

    win.callOnFlip(port.setData, BLOCK_START_TRIGGER)
    win.flip()
    port.setData(0)

    for trial in trials:
        if present_trial(win, port, fixation, word_stim, trial) == "escape":
            break

    win.callOnFlip(port.setData, BLOCK_END_TRIGGER)
    win.flip()
    port.setData(0)
    win.close()
    core.quit()


if __name__ == "__main__":
    main()
